"""Build the readable acceptance report from saved execution evidence."""
from pathlib import Path
import json
r=Path(__file__).resolve().parents[1]
metrics=json.loads((r/'reports/ds2_metrics.json').read_text())
q=metrics['quantized_current_irn'];rr=metrics['RR_logistic_baseline']
checks=[
('Original preservation','PASS','Original ZIP, 180-file hash inventory and pre-change backups included.','backups/original_project.zip'),
('Dataset','PASS','All 132 publisher-verified files for 44 records parsed; record 119 repaired.','reports/dataset_manifest.json'),
('Preparation','PASS','100,679 complete-window beats; 54 boundary exclusions; real ECG training only.','reports/dataset_preparation.json'),
('Training','PASS','300 epochs: 30 floating and 270 QAT; 18 DS1 fit and 4 DS1 validation records.','reports/training_execution.json'),
('QAT memorization diagnostic','PASS','Ten real DS1 beats memorized; diagnostic accuracy 100%.','reports/real_qat_memorization.json'),
('DS2 evaluation','PASS','49,688 beats from all 22 DS2 records; RR and QNN score identical beat identities.','reports/ds2_metrics.json'),
('Accuracy >99.6%','FAIL',f'Observed {q["accuracy"]:.4%}, macro-F1 {q["macro_f1"]:.6f}.','reports/ds2_metrics.json'),
('Original golden replay','PASS','8/8 exact; all-F predictions reproduce the original initialization.','reports/baseline/qnn.log'),
('Trained RTL replay','PASS','10/10 real DS2 vectors: all five signed logits and classes match.','reports/trained_qnn_checked.log'),
('Batched float32 QAT parity','FAIL','Numerical deviations observed; frozen inference uses float64 integer emulation.','reports/batched_inference_diagnostic.json'),
('Frozen inference oracle','PASS','All 21 operation tensors and batched final logits match on ten real DS2 beats.','experiments/ds2_evaluation/EVALUATED.json'),
('Annotated-beat trace','PASS','Record 100, annotation 2, R sample 370 traced through CWT, memory and class N.','reports/beat_trace.json'),
('Legacy frozen streaming replay','PASS','267/267 frozen events; a separate detector/tree/small-CNN path.','reports/baseline/streaming_frozen_replay.json'),
('MATLAB/Octave reruns','BLOCKED','Runtime unavailable; archived stage logs are not current execution evidence.','sim/verify_current_export.m'),
('Cadence CSV replay','PASS','All 1,501 supplied ADC codes and 3,600 legacy map tokens reproduced.','reports/cadence_adapter.json'),
('Trained Cadence RTL replay','PASS','1/1 exact signed-logit replay; no classification ground truth for this waveform.','reports/afe_trained_checked.log'),
('Board wrapper simulation','PASS','4/4 selections: logits, LEDs and display segments; scan reset repaired.','reports/trained_board_checked.json'),
('Board constraints','PASS','All 21 used pin assignments checked against Digilent master constraints.','rtl/basys3/basys3.xdc'),
('Generic xc7 synthesis','PASS','Core and board mapped netlists produced; zero static-check problems.','reports/synthesis/trained_board/result.json'),
('Latency conversion','ESTIMATED','883,718 simulated cycles imply 8.83718 ms at an assumed achieved 100 MHz.','reports/performance_summary.json'),
('Latency <0.35 ms','FAIL','8.83718 ms under the declared 100 MHz assumption; host CWT and acquisition excluded.','reports/PERFORMANCE.md'),
('Vivado implementation/timing','BLOCKED','Vivado unavailable; no placement, routing or timing closure result.','fpga/vivado_qcare.tcl'),
('Power/energy <0.07 mJ','NOT TESTED','No measured power or energy; no fabricated energy estimate.','reports/PERFORMANCE.md'),
('Programming/physical ADC','NOT TESTED','No FPGA programming or physical ADC acquisition executed.','reports/trained_board_checked.json'),
('AFE electrical acceptance','BLOCKED','No Spectre runtime or schematic/VM database in the confirmed ZIP; earlier _ocn_ path is absent.','sim/AFE_CADENCE_COSIM.md'),
('Post-synthesis equivalence','NOT TESTED','No formal or gate-level functional equivalence run.','reports/PERFORMANCE.md'),
('Provenance guards','PASS','132 raw files, four caches and checkpoint provenance checked; changed/missing inputs rejected.','reports/provenance_checks.json'),
('Other research experiments','NOT TESTED','No intra-patient retraining, TTA, replacement fusion model or AFE-conditioned DS2 run.','README.md')]
(r/'reports/acceptance.json').write_text(json.dumps([dict(check=a,status=b,result=c,evidence=d) for a,b,c,d in checks],indent=2))
status=['# Q-CARE status — 2026-10-26','', '**Accuracy and latency targets were not achieved.** Software, digital RTL and generic synthesis results are recorded below. Physical FPGA and AFE acceptance remain open.','', '| Check | Status | Result and evidence |','|---|---|---|']
for a,b,c,d in checks:status.append(f'| {a} | **{b}** | {c} [{d}]({d}) |')
status += ['', 'PASS applies only to the named check. It does not imply accuracy-target, timing, clinical or physical acceptance. The five-class QNN remains separate from the legacy streaming detector. CWT runs on the host and the board demo uses stored maps. Conventional records 201/202 share a subject across DS1/DS2.','', 'See [README](README.md), [final report](reports/FINAL_REPORT.md), [engineering audit](reports/ENGINEERING_AUDIT.md), and [performance](reports/PERFORMANCE.md).']
(r/'STATUS.md').write_text('\n'.join(status)+'\n')
lines=['# Q-CARE executed results — 2026-10-26','', f'**The requested >99.6% accuracy was not achieved.** The frozen current quantized model obtained **{q["accuracy"]:.4%} accuracy and {q["macro_f1"]:.6f} macro-F1** on 49,688 annotated beats from all 22 DS2 records. The report documents a real-data baseline and repaired verification path; it does not establish an improvement over the paper.','', '| Saved method | Accuracy | Macro-F1 | 95% record-bootstrap accuracy interval |','|---|---:|---:|---|']
for name,v in metrics.items():
 lo,hi=v['uncertainty']['accuracy_95_ci'];lines.append(f'| {name} | {v["accuracy"]:.4%} | {v["macro_f1"]:.6f} | {lo:.2%}–{hi:.2%} |')
lines += ['', 'Every method uses the same fit, validation and test records, annotation mapping, boundary exclusions and scored test beat identities. Fitting uses 18 DS1 records; validation uses 108, 114, 209 and 223; testing uses all 22 DS2 records. Included beats are 41,743 / 9,248 / 49,688, with incomplete-window exclusions of 26 / 4 / 24. No required record is missing. Records 201 and 202 are the same person in the conventional split, so strict subject independence cannot be claimed.','', 'Uncertainty intervals use 1,000 record-cluster bootstrap resamples with seed 26. They describe variation across the fixed DS2 records. Q has only seven test beats and eight DS1 beats; validation contains no Q. Macro-F1 averages all five classes, including zero-valued F1. These intervals do not establish independent-patient clinical validation.','', '| Model | Class | Support | Sensitivity | Positive predictivity | F1 | Specificity |','|---|---|---:|---:|---:|---:|---:|']
for name,v in [('Quantized IRN',q),('RR logistic',rr)]:
 for c,z in v['per_class'].items():lines.append(f'| {name} | {c} | {z["support"]} | {z["sensitivity"]:.6f} | {z["positive_predictivity"]:.6f} | {z["f1"]:.6f} | {z["specificity"]:.6f} |')
lines += ['', 'The QNN has no true-positive F or Q beats, and S sensitivity is 11.16%. Both trained methods have accuracy below the N-class prevalence of 89.0275% in DS2. The RR baseline has higher macro-F1 than the QNN. Accuracy alone therefore obscures the class-imbalance problem. RR features use past annotated intervals and ratios, a fit-only StandardScaler and class-balanced logistic regression (C=1); an independent R detector was not benchmarked.','', 'Confusion matrices use true classes as rows and predictions as columns, ordered N, S, V, F, Q. All metrics and raw matrices are in `reports/ds2_metrics.json`; saved per-beat predictions are in `experiments/ds2_evaluation/`. Neither model used DS2 for fitting, calibration, early stopping or checkpoint selection. A mechanical inference-parity repair followed a failed initial export check: the frozen weights and scales stayed unchanged, while quantized evaluation used float64 power-of-two integer emulation. The initial failure and numerical diagnostic remain available. Float32 training and validation selection are preserved as executed.','', 'The current architecture remains unchanged: 14 convolutions, four IRN blocks, 9,144 weights and 149 biases. Its formats are signed 4-bit weights, 8-bit inputs, post-ReLU activations in [0,127], signed 16-bit biases, 32-bit accumulators and 24-bit logits. It differs from the paper architecture. The 30 floating plus 270 QAT epochs, frozen-scale calibration and cosine schedule are declared choices. Training used real annotated ECG and shifted real windows only.','', 'Executed consistency checks include the original 8/8 QNN vectors, 10/10 new real DS2 vectors (every signed logit), all 21 operation tensors on ten real beats, 4/4 board-wrapper selections including display segments, one trained Cadence-waveform RTL replay, and 267/267 legacy frozen streaming events. These vector suites do not mean that all 49,688 DS2 beats were simulated in RTL. The original all-F initialization remains preserved.','', 'Generic Xilinx 7-series synthesis passed. The core uses 2,543 LUT primitives, 647 FFs, 20 RAMB36 blocks and 23 DSPs. The full stored-map wrapper uses 2,592 LUT primitives, 737 FFs, 20 RAMB36 plus 7 RAMB18 blocks and 24 DSPs. Both completed static checks with zero reported problems. These are mapped synthesis counts, without placement or timing proof.','', 'RTL simulation counts 883,718 engine cycles. At an assumed achieved 100 MHz, derived engine latency is 8.83718 ms (ESTIMATED), above the <0.35 ms target. Host CWT, map loading, acquisition and debounce are excluded. Power, energy and physical operation remain NOT TESTED. Vivado implementation, MATLAB reruns and Cadence/Spectre runs are BLOCKED by unavailable tools. Corresponding source and instructions are included.','', 'The provisional ADC is 12-bit offset-binary over ±1 V at 500 Hz, followed by linear interpolation to 360 Hz. Cadence peak selection is heuristic, with no annotation or class ground truth. CSV replay does not verify AFE gain, noise, bandwidth, clamping, overload recovery, CMFB or bandgap behavior.','', 'The refreshed ZIP includes all 44 verified source records, the original archive and backups, code, RTL, constraints, trained checkpoints, reports and separate golden vectors. Large regenerable CWT arrays and compiled simulator executables are excluded. Preparation metadata and regeneration commands are included. See `README.md`, `STATUS.md`, `reports/ENGINEERING_AUDIT.md`, `reports/PERFORMANCE.md`, `reports/modified_files.json` and `data/ATTRIBUTION.md`.']
(r/'reports/FINAL_REPORT.md').write_text('\n'.join(lines)+'\n')
print('PASS: status and report built from saved evidence')
